/**
 * The glossary (FRONTEND.md §4.3): every entry well formed, the quoted ones verbatim from the
 * approved disclosures, the placeholders filled, every label one the UI writes, and the whole text
 * in FRONTEND.md §4.3 word for word — approved as written by the owner on 2026-10-11 (thirteenth
 * round): a changed entry (its text, its term, its labels, or the paragraphs it quotes) fails here
 * until the doc — regenerated by `scripts/owner-copy.ts --doc` — carries it.
 */
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { FLAG_META } from '../features/markets/shared/marketFlags.ts';
import { CAP_TEXT } from '../features/short/ui.tsx';
import { readRepo } from '../test/repo.ts';
import { DISCLOSURES } from './disclosures.ts';
import { programError } from './errors.ts';
import { GLOSSARY, GLOSSARY_UI, type GlossaryEntry, type GlossaryId, glossaryFor } from './glossary.ts';
import { GLOSSARY_SOURCES } from './glossarySources.ts';
import { glossaryHasVars, glossaryText, glossaryVars } from './glossaryText.ts';

const entries = Object.entries(GLOSSARY) as [GlossaryId, GlossaryEntry][];

/** The UI's source text (components and pages, tests and the glossary itself excluded). */
function uiSource(): string {
    const root = join(process.cwd(), 'src');
    const out: string[] = [];
    const walk = (dir: string) => {
        for (const name of readdirSync(dir)) {
            const p = join(dir, name);
            if (statSync(p).isDirectory()) walk(p);
            else if (/\.tsx?$/.test(name) && !/\.test\.tsx?$/.test(name) && !/[\\/]config[\\/]glossary\w*\.ts$/.test(p))
                out.push(readFileSync(p, 'utf8'));
        }
    };
    walk(root);
    return out.join('\n').replaceAll('&amp;', '&');
}

describe('glossary', () => {
    it('keys every entry by its id, with a term, a text or a quote (never both), and sources', () => {
        for (const [key, e] of entries) {
            expect(e.id, key).toBe(key);
            expect(e.term.length, key).toBeGreaterThan(0);
            expect(GLOSSARY_SOURCES[key]?.length, `${key}: sources`).toBeGreaterThan(0);
            expect(!!e.text !== !!e.quote, `${key}: text xor quote`).toBe(true);
        }
    });

    it('quotes the approved disclosures verbatim', () => {
        for (const [id, e] of entries) {
            if (!e.quote) continue;
            const body = DISCLOSURES[e.quote.disclosure].body;
            const expected = e.quote.paragraphs.map((p) => {
                expect(body[p], `${id} ¶${p + 1}`).toBeDefined();
                return body[p];
            });
            // The locked-shares quote carries {lockGrace}: filled like the disclosure's own.
            const vars = glossaryVars({ lockGraceS: 86_400, lumpVestS: 259_200 });
            expect(glossaryText(id, vars)).toBe(expected.join(' ').replace('{lockGrace}', '1 day'));
        }
        // "Opens paused" is the program's own message for 6050, as the market page's banner shows it.
        expect(glossaryText('flagOpensPaused')).toBe(programError(6050)?.message);
    });

    it('fills its placeholders from the config, and with words before it is read', () => {
        const vars = glossaryVars({ lockGraceS: 86_400, lumpVestS: 259_200 });
        expect(glossaryText('vesting', vars)).toContain('over 3 days');
        expect(glossaryText('vesting')).toContain('over the vesting period');
        for (const [id] of entries) expect(glossaryText(id, vars), id).not.toMatch(/\{\w+\}/);
        expect(() => glossaryText('vesting', {})).toThrow(/missing \{vestPeriod\}/);
        // Only the entries with placeholders read the live config.
        expect(entries.filter(([id]) => glossaryHasVars(id)).map(([id]) => id)).toEqual(['vesting', 'locked']);
        expect(Object.keys(GLOSSARY_SOURCES).sort()).toEqual(entries.map(([id]) => id).sort());
    });

    it('attaches by the UI’s exact labels, each label to one entry', () => {
        expect(glossaryFor('CR')).toBe('cr');
        expect(glossaryFor(' Q owed ')).toBe('q');
        expect(glossaryFor('Tokens borrowed (ΣQ)')).toBe('sumQ');
        expect(glossaryFor('Rate (APR)')).toBe('rentApr');
        expect(glossaryFor('Share epoch')).toBe('shareEpoch');
        expect(glossaryFor('Pool share')).toBe('poolShare');
        expect(glossaryFor('Settled in SOL (S1 / S2 / S3)')).toBe('settlement');
        expect(glossaryFor('Price (EMA)')).toBe('ema');
        expect(glossaryFor('nothing like it')).toBeUndefined();
        expect(glossaryFor(42)).toBeUndefined();
        // Every flag badge and every size cap the UI names has an entry.
        for (const { label } of Object.values(FLAG_META)) expect(glossaryFor(label), label).toBeDefined();
        for (const label of Object.values(CAP_TEXT)) expect(glossaryFor(label), label).toBeDefined();
    });

    it('only lists labels the UI writes', () => {
        const src = uiSource();
        for (const [id, e] of entries) for (const l of e.labels) expect(src.includes(l), `${id}: “${l}”`).toBe(true);
    });

    it('is in FRONTEND.md §4.3 word for word, as the owner approved it on 2026-10-11', () => {
        const doc = readRepo('docs/design/FRONTEND.md');
        const s43 = doc.slice(doc.indexOf('### 4.3'), doc.indexOf('## 5.'));
        expect(s43).not.toContain('pending owner approval');
        expect(s43).toContain('approved as written by the owner on 2026-10-11 (thirteenth');
        // The control's two strings.
        expect(Object.keys(GLOSSARY_UI)).toHaveLength(2);
        for (const [id, text] of Object.entries(GLOSSARY_UI))
            expect(s43, id).toContain(`- \`${id}\` (the ⓘ):\n  > ${text}\n`);
        // Every entry: its term, the labels it sits beside, and its text — for a quote, the
        // disclosure and the paragraphs it quotes, then their words as the entry shows them (so a
        // paragraph added, dropped or moved in the disclosure changes §4.3 too), which §4.2 carries
        // verbatim.
        expect(entries).toHaveLength(78);
        for (const [id, e] of entries) {
            const beside = e.labels.length ? e.labels.map((l) => `“${l}”`).join(', ') : 'its status bar item';
            if (e.quote) {
                const ref = `D:${e.quote.disclosure} ${e.quote.paragraphs.map((p) => `¶${p + 1}`).join(', ')}`;
                const d = DISCLOSURES[e.quote.disclosure];
                const quoted = e.quote.paragraphs.map((p) => d.body[p]).join(' ');
                expect(s43, id).toContain(
                    `- \`glossary.${id}\` — ${e.term}; beside ${beside}: *verbatim, ${ref}*\n  > ${quoted}\n`,
                );
                const s42 = doc.slice(doc.indexOf(`#### \`${d.id}\` — ${d.title}`), doc.indexOf('### 4.3'));
                for (const p of e.quote.paragraphs)
                    expect(s42.split('\n#### ')[0], `${id} ¶${p + 1}`).toContain(`> ${d.body[p]}`);
            } else {
                expect(s43, id).toContain(`- \`glossary.${id}\` (${e.term}; beside ${beside}):\n  > ${e.text}\n`);
            }
        }
    });
});
